import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百零五章 触不能生起界","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/105第一百零五章 触不能生起界.md","filePath":"meditation/巴利文大藏经/105第一百零五章 触不能生起界.md"}'),r={name:"meditation/巴利文大藏经/105第一百零五章 触不能生起界.md"};function _(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百零五章-触不能生起界" tabindex="-1">第一百零五章 触不能生起界 <a class="header-anchor" href="#第一百零五章-触不能生起界" aria-label="Permalink to &quot;第一百零五章 触不能生起界&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部14相应3经/非种种触经(界相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，以种种界（界解释，见第一百零三章）为前提条件生起种种触（触解释，见第一百零四章），弟子们你们要注意，不要弄颠倒了，以种种触为前提条件不能生起种种界！</p><p>弟子们，什么是种种界呢？就是：眼界、耳界、鼻界、舌界、身界、意界（眼界、耳界、鼻界、舌界、身界、意界解释，见第一百零三章），弟子们，这些就被称为种种界。</p><p>弟子们，什么是以种种界为前提条件生起种种触呢？什么是以种种触为前提条件不能生起种种界呢？就是：以眼界为前提条件生起眼触（眼触解释，见第一百零四章），要注意，不要弄颠倒了，以眼触为前提条件不能生起眼界！</p><p>以耳界为前提条件生起耳触（耳触解释，见第一百零四章），要注意，不要弄颠倒了，以耳触为前提条件不能生起耳界！</p><p>以鼻界为前提条件生起鼻触（鼻触解释，见第一百零四章），要注意，不要弄颠倒了，以鼻触为前提条件不能生起鼻界！</p><p>以舌界为前提条件生起舌触（舌触解释，见第一百零四章），要注意，不要弄颠倒了，以舌触为前提条件不能生起舌界！</p><p>以身界为前提条件生起身触（身触解释，见第一百零四章），要注意，不要弄颠倒了，以身触为前提条件不能生起身界！</p><p>以意界为前提条件生起意触（意触解释，见第一百零四章），要注意，不要弄颠倒了，以意触为前提条件不能生起意界！</p><p>弟子们，这就是以种种界为前提条件生起种种触，以种种触为前提条件不能生起种种界的法义。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',13)]))}const f=e(r,[["render",_]]);export{m as __pageData,f as default};
